ga48(){return"\u0695\u06d5\u0646\u06af (\u0647\u06ce\u06a9\u0633\u060c \u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 FFB8763F)"},
ga2H(){return"\u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646\u06cc \u06a9\u06d5\u06cc\u0633"},
