gagr(){return"\u0647\u06cc\u0686 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce\u06a9 \u0644\u06d5\u06af\u06d5\u06b5 \u0626\u06d5\u0645 \u06af\u06d5\u0695\u0627\u0646\u06d5 \u0646\u0627\u06af\u0648\u0646\u062c\u06ce\u062a."},
gagS(){return"\u06af\u06d5\u0695\u0627\u0646 \u0644\u06d5 \u067e\u0632\u06cc\u0634\u06a9\u06d5\u06a9\u0627\u0646\u2026"},
