gRQ(){return'\u06a9\u0627\u062a\u06ce\u06a9 \u0686\u0627\u0644\u0627\u06a9\u06d5\u060c \u0644\u06d5 "\u06a9\u06d5\u06cc\u0633\u06cc \u0646\u0648\u06ce"\u062f\u0627 \u062f\u0648\u06af\u0645\u06d5\u06cc "\u0633\u06a9\u0627\u0646\u06cc \u06a9\u0627\u063a\u06d5\u0632\u06cc \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc" \u062f\u06d5\u0631\u062f\u06d5\u06a9\u06d5\u0648\u06ce\u062a \u06a9\u06d5 \u0648\u06ce\u0646\u06d5\u06cc \u06a9\u0627\u063a\u06d5\u0632\u06cc \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc \u06a9\u06d5\u06cc\u0633\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u062f\u06d5\u062e\u0648\u06ce\u0646\u06ce\u062a\u06d5\u0648\u06d5 \u0648 \u0641\u06c6\u0631\u0645\u06d5\u06a9\u06d5 \u067e\u06ce\u0634\u200c\u067e\u0695\u062f\u06d5\u06a9\u0627\u062a\u06d5\u0648\u06d5 \u0628\u06c6 \u067e\u06ce\u062f\u0627\u0686\u0648\u0648\u0646\u06d5\u0648\u06d5. \u0647\u06d5\u0631 \u0633\u06a9\u0627\u0646\u06ce\u06a9 \u0628\u0627\u0646\u06af\u0647\u06ce\u0634\u062a\u0646\u06ce\u06a9\u06cc AI \u0628\u06d5\u06a9\u0627\u0631\u062f\u06d5\u0647\u06ce\u0646\u06ce\u062a.'},
RO(a){return A.aB(a,null,this.a,null,"\u0661 \u06a9\u0631\u06ce\u062f\u06cc\u062a\u06cc \u0633\u06a9\u0627\u0646 \u0645\u0627\u0648\u06d5",""+a+" \u06a9\u0631\u06ce\u062f\u06cc\u062a\u06cc \u0633\u06a9\u0627\u0646 \u0645\u0627\u0648\u06d5",null,"\u0647\u06cc\u0686 \u06a9\u0631\u06ce\u062f\u06cc\u062a\u06cc \u0633\u06a9\u0627\u0646 \u0646\u06d5\u0645\u0627\u0648\u06d5 \u2014 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc \u0628\u06d5 07748133883 \u0628\u06a9\u06d5 \u0628\u06c6 \u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646")},
