gagN(){return"\u062e\u0648\u06ce\u0646\u062f\u0646\u06d5\u0648\u06d5\u06cc \u06a9\u0627\u063a\u06d5\u0632\u2026"},
agL(a){return"\u0633\u06a9\u0627\u0646\u06cc \u06a9\u0627\u063a\u06d5\u0632 \u0633\u06d5\u0631\u06a9\u06d5\u0648\u062a\u0648\u0648 \u0646\u06d5\u0628\u0648\u0648: "+a},
gagM(){return"\u0647\u06cc\u0686 \u0634\u062a\u06ce\u06a9 \u0644\u06d5\u0648 \u0648\u06ce\u0646\u06d5\u06cc\u06d5 \u0646\u06d5\u062e\u0648\u06ce\u0646\u0631\u0627\u06cc\u06d5\u0648\u06d5."},
