gKS(){return"\u0628\u06d5\u0695\u06ce\u0648\u06d5\u0628\u0631\u062f\u0646\u06cc \u06a9\u0627\u0631\u067e\u06ce\u06a9\u06d5\u0631\u0627\u0646\u06cc \u0633\u06a9\u06d5\u0646\u06d5\u0631\u06cc \u0626\u06d5\u0645 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5"},
OA(a){return"\u06a9\u0627\u0631\u067e\u06ce\u06a9\u06d5\u0631\u0627\u0646\u06cc \u0633\u06a9\u06d5\u0646\u06d5\u0631 \u2014 "+a},
gOD(){return"\u0646\u0627\u0648\u06cc \u06a9\u0627\u0631\u067e\u06ce\u06a9\u06d5\u0631\u06cc \u0646\u0648\u06ce"},
