gOB(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u06a9\u0627\u0631\u067e\u06ce\u06a9\u06d5\u0631\u06ce\u06a9\u06cc \u0633\u06a9\u06d5\u0646\u06d5\u0631 \u0628\u06c6 \u0626\u06d5\u0645 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5 \u0646\u06cc\u06cc\u06d5."},
gOz(){return"\u0646\u0627\u0686\u0627\u0644\u0627\u06a9\u06a9\u0631\u062f\u0646"},
gOy(){return"\u0686\u0627\u0644\u0627\u06a9\u06a9\u0631\u062f\u0646"},
ga1o(){return"\u06a9\u0627\u0631\u067e\u06ce\u06a9\u06d5\u0631\u06cc \u0633\u06a9\u06d5\u0646\u06d5\u0631"},
gakh(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u06a9\u0627\u06b5\u0627 \u0644\u06d5 \u06a9\u06c6\u06af\u0627 \u062f\u06d5\u0631\u0628\u0647\u06ce\u0646\u06ce\u062a \u0628\u06d5 \u0628\u0627\u0631\u06a9\u06c6\u062f"},
