ga2E(){return"\u0628\u06c6 \u06a9\u0627\u0631\u06ce\u0646 \u062a\u0627\u062c/\u067e\u0631\u06ce \u2014 \u062e\u0627\u0646\u06ce\u0646 \u06a4\u0627\u0644\u0627 \u06cc\u06ce\u0646 \u062f\u06cc\u0632\u0627\u06cc\u0646\u0627 \u0645\u0627\u0631\u062c\u0646\u06ce / \u062f\u06cc\u0632\u0627\u06cc\u0646\u0627 \u06a9\u06c6\u0646\u062a\u0627\u06a9\u062a\u06ce / \u062f\u06cc\u0632\u0627\u06cc\u0646\u0627 \u067e\u06c6\u0646\u062a\u06cc\u06a9\u06ce / \u062a\u06d5\u0645\u06d5\u0646-\u0631\u06d5\u06af\u06d5\u0632 \u0644 \u0633\u06d5\u0631 \u0644\u06ce\u0628\u0644\u06ce \u0686\u0627\u067e\u06a9\u0631\u06cc \u0632\u06ce\u062f\u06d5 \u062f\u06a9\u06d5\u062a \u062f\u0627 \u062a\u06d5\u06a9\u0646\u06cc\u06a9\u0627\u0631 \u0628 \u062f\u06d5\u0633\u062a\u06cc \u0646\u06cc\u0634\u0627\u0646 \u0628\u06a9\u06d5\u062a. \u06a4\u06ce \u0628\u06cc\u0645\u0631\u06cc\u0646\u06d5 \u067e\u0634\u062a\u06cc \u062a\u06d5 \u0647\u06d5\u0645\u0627\u0646 \u0648\u0631\u062f\u06d5\u06a9\u0627\u0631\u06cc \u0648\u06d5\u06a9 \u062a\u0627\u06cc\u0628\u06d5\u062a\u0645\u06d5\u0646\u062f\u06cc\u06ce\u0646 \u0631\u0627\u0633\u062a\u06d5\u0642\u06cc\u0646\u06d5 \u0644 \u0633\u06d5\u0631 \u06a4\u06cc \u062c\u06c6\u0631\u06ce \u06a9\u06d5\u06cc\u0633\u06cc \u0632\u06ce\u062f\u06d5 \u06a9\u0631\u06cc\u0646 (\u062f\u0627 \u0644\u06ce\u0628\u0644 \u0646\u0631\u062e\u06ce \u0647\u06d5\u0644\u0628\u0698\u0627\u0631\u062a\u06cc \u06cc\u06ce \u0631\u0627\u0633\u062a\u06d5\u0642\u06cc\u0646\u06d5 \u067e\u06cc\u0634\u0627\u0646 \u0628\u062f\u06d5\u062a \u0644 \u062c\u0647\u06ce \u062e\u0627\u0646\u06d5\u06cc\u06d5\u06a9\u0627 \u06a4\u0627\u0644\u0627)."},
ga2D(){return"\u0628\u0627\u0632\u0646\u06ce\u0646 \u067e\u0631\u06ce \u0644 \u0633\u06d5\u0631 \u0646\u06d5\u062e\u0634\u06ce \u062f\u062f\u0627\u0646\u0627\u0646"},
ga2C(){return"\u0628\u06c6 \u06a9\u0627\u0631\u06ce\u0646 \u062a\u0627\u062c \u0648 \u067e\u0631\u06ce \u0648 \u0626\u06cc\u0645\u067e\u0644\u0627\u0646\u062a\u06ce: \u0628\u0627\u0632\u0646\u06d5\u06a9 \u062f \u0646\u0627\u0641\u0628\u06d5\u0631\u0627 \u062f\u0648\u0648 \u062f\u062f\u0627\u0646\u06ce\u0646 \u0647\u06d5\u0644\u0628\u0698\u0627\u0631\u062a\u06cc \u062f\u0627 \u0648\u0627\u0646 \u0648\u06d5\u06a9 \u067e\u0631 \u06af\u0631\u06ce \u062f\u062f\u06d5\u062a\u060c \u0648 \u067e\u0631 \u0644 \u0633\u06d5\u0631 \u0644\u06ce\u0628\u0644\u06ce \u062f\u0647\u06ce\u062a\u06d5 \u0686\u0627\u067e\u06a9\u0631\u0646. \u0628\u06c6 \u0648\u0627\u0646 \u062c\u06c6\u0631\u0627\u0646 \u06cc\u06ce\u0646 \u0686 \u062c\u0627\u0631\u0627\u0646 \u067e\u0631 \u0646\u06cc\u0646\u0646 (\u06a4\u06cc\u0646\u06cc\u0631\u060c \u062f\u062f\u0627\u0646\u06ce\u0646 \u062f\u06d5\u0633\u062a\u06a9\u0631\u062f\u060c \u0626\u0627\u0645\u06cc\u0631) \u0628\u06cc\u0645\u0631\u06cc\u0646\u06d5."},
ga4a(){return"\u0642\u06c6\u0646\u0627\u063a\u0627 \u062f\u0648\u0648\u0695\u06cc\u0627\u0646\u0627 \u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u0646\u06ce"},
ga49(){return"\u062f\u06d5\u0645\u06ce \u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u06d5\u06a9\u0627 \u062c\u06c6\u0631\u06ce\u0646 \u062a\u06ce\u06a9\u06d5\u0644 \u062f\u0647\u06ce\u062a\u06d5 \u0633\u06a9\u0627\u0646\u06a9\u0631\u0646 \u0628\u06c6 \u0686\u0648\u0648\u0646\u06d5 \u0646\u0627\u06a4 (\u06cc\u0627\u0646 \u062f\u06d5\u0631\u06a9\u06d5\u0641\u062a\u0646 \u0698) \u06a4\u06ce \u0642\u06c6\u0646\u0627\u063a\u06ce\u060c \u062a\u0646\u06ce \u0626\u06d5\u0648 \u06cc\u06d5\u06a9\u06ce\u0646 \u0645\u0627\u062f\u062f\u0627 \u0648\u0627\u0646 \u062f\u06af\u06d5\u0644 \u0626\u0627\u0645\u06cc\u0631\u06ce \u062a\u06d5\u06a9\u0646\u06cc\u06a9\u0627\u0631\u06ce \u0633\u06a9\u0627\u0646\u06a9\u06d5\u0631 \u062f\u06af\u0648\u0646\u062c\u06cc\u062a \u067e\u06ce\u0634\u06a4\u06d5 \u062f\u0686\u0646. \u06a4\u06ce \u0644 \u0633\u06d5\u0631 \u0642\u06c6\u0646\u0627\u063a\u0627 \u0645\u06cc\u0644\u06cc\u0646\u06af/\u067e\u0631\u06ce\u0633\u06ce \u062f\u0627\u0628\u0646\u06ce."},
ga3q(){return"\u0631\u06ce\u0695\u06d5\u0648\u0627 \u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u0646\u06ce"},
ga3p(){return"\u0644 \u0642\u06c6\u0646\u0627\u063a\u0627 \u062f\u0648\u0648\u0695\u06cc\u0627\u0646\u0627 \u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u0646\u06ce\u060c \u062a\u0646\u06ce \u0633\u06a9\u0627\u0646\u0627 \u06a4\u06cc \u062a\u06d5\u06a9\u0646\u06cc\u06a9\u0627\u0631\u06cc \u0626\u06d5\u0648 \u06cc\u06d5\u06a9\u06ce\u0646 \u06a4\u06ce \u0645\u0627\u062f\u062f\u06ce \u0628\u06a9\u0627\u0631\u062f\u0626\u06cc\u0646\u0646 \u062f \u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u06d5\u06a9\u0627 \u062c\u06c6\u0631\u06ce\u0646 \u062a\u06ce\u06a9\u06d5\u0644 \u062f\u0627 \u067e\u06ce\u0634\u06a4\u06d5 \u062f\u0628\u06d5\u062a."},
ga3r(){return"\u0628\u06ce \u0631\u06ce\u0695\u06d5\u0648 (\u062f\u06af\u06d5\u0644 \u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u06ce \u062f\u0686\u06cc\u062a)"},
ga2w(){return"\u062c\u06c6\u0631\u06d5\u06a9\u06ce \u06a9\u06d5\u06cc\u0633\u06cc \u06cc\u06ce \u0646\u0648\u06cc \u0628 \u062e\u06c6 \u0631\u06ce\u0695\u06d5\u0648\u0627 \u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u06cc\u0627 \u0628\u06d5\u0631\u0647\u06d5\u0645\u0626\u06cc\u0646\u0627\u0646\u06ce \u0628 6 \u0642\u06c6\u0646\u0627\u063a\u0627\u0646 \u0648\u06d5\u0631\u062f\u06af\u0631\u06cc\u062a (\u0648 \u0626\u06d5\u06af\u06d5\u0631 \u0631\u06d5\u0646\u06af\u06cc \u0628\u06a9\u0627\u0631\u0628\u06cc\u0646\u06cc\u062a\u060c \u0644\u06cc\u0633\u062a\u0627 \u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u06cc\u0627 16 \u0631\u06d5\u0646\u06af\u0627\u0646) \u2014 \u0647\u06d5\u0631 \u062f\u0648\u0648 \u067e\u0627\u0634\u0627\u0646 \u0628 \u062a\u06d5\u0645\u0627\u0645\u06cc \u062f\u0647\u06ce\u0646\u06d5 \u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u0646."},
ga2v(){return"\u06a9\u0648\u0631\u062a\u06a9\u0631\u06cc (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
ga2u(){return"\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 CR"},
gId(){return"\u0646\u06d5\u0686\u0627\u0644\u0627\u06a9"},
ga2R(){return"\u06a9\u06c6\u0645\u0628\u06c6"},
