ga7n(){return"\u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u0627 \u0642\u06d5\u0631\u0632\u06ce \u062f\u06d5\u0633\u062a\u067e\u06ce\u06a9\u06ce"},
ga7h(){return"\u062e\u06d5\u0631\u062c\u06cc"},
ga7v(){return"\u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631"},
ga7t(){return"\u067e\u0633\u0648\u0648\u0644\u06d5\u06cc\u06ce\u0646 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u0627\u0646"},
ga7u(){return"\u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06ce\u0646 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u0627\u0646"},
ga7j(){return"\u06a9\u0627\u0631\u0645\u06d5\u0646\u062f"},
ga7r(){return"\u0645\u0648\u0648\u0686\u06d5"},
ga7q(){return"\u0633\u0646\u062f\u0648\u0642"},
ga7e(){return"\u062c\u06c6\u0631\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646"},
ga7l(){return"\u0645\u0627\u062f\u062f\u06d5"},
gaj7(){return"\u062f\u0634\u06ce\u062a \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627 \u0647\u0627\u062a\u06cc\u06d5 \u0647\u0646\u0627\u0631\u062a\u0646 \u06a4\u06d5\u06af\u06d5\u0631\u06cc\u0646\u06cc\u062a\u06d5 \u0628\u06d5\u0631\u0647\u06d5\u0645\u0647\u06ce\u0646\u0627\u0646\u06ce \u0628\u06c6 \u06af\u0648\u0647\u06c6\u0631\u06cc\u0646\u06ce"},
gaj2(){return"\u062f\u0634\u06ce\u062a \u0641\u0627\u06cc\u0644\u06d5\u06a9\u06ce \u06a9\u06d5\u06cc\u0633\u06ce \u06cc\u06ce \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce \u0628\u0627\u0631\u06a9\u0631\u06cc \u0698\u06ce\u0628\u0628\u06d5\u062a \u06cc\u0627\u0646 \u0628\u06af\u0648\u0647\u06c6\u0695\u06cc\u062a"},
gaj9(){return"\u062f\u0634\u06ce\u062a \u062a\u06ce\u0686\u0648\u0648\u0646 \u0648 \u0642\u0627\u0632\u0627\u0646\u062c\u06ce \u062f \u06a9\u06d5\u06cc\u0633\u06ce \u062f\u0627 \u0628\u0628\u06cc\u0646\u06cc\u062a (\u0628\u0647\u0627 \u06cc\u06ce \u062c\u0648\u062f\u0627\u06cc\u06d5)"},
gagk(){return"\u0647\u06ce\u0644\u06d5\u06a9\u06ce \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5\u2026"},
gagl(){return"\u0628\u06d5\u0631\u06cc \u067e\u0627\u0634\u06a9\u06d5\u0641\u062a\u06a9\u0631\u0646\u06ce \u0647\u06ce\u0644\u0627 \u06a4\u06cc \u06a9\u06d5\u06cc\u0633\u06cc \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5."},
gRr(){return"\u0626\u0627\u06af\u06d5\u0647\u062f\u0627\u0631\u06a9\u0631\u0646 \u062f\u06d5\u0645\u06ce \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627 \u0646\u0648\u06cc \u0647\u0627\u0648\u067e\u06ce\u0686 \u0646\u06cc\u0646\u06d5"},
gRs(){return"\u0626\u06d5\u06af\u06d5\u0631 \u0686 \u0641\u0627\u06cc\u0644 (\u0648\u06ce\u0646\u06d5\u060c \u06a4\u06cc\u062f\u06cc\u06c6\u060c \u0633\u06a9\u0627\u0646 \u06cc\u0627\u0646 \u0628\u06d5\u0644\u06af\u06d5\u0646\u0627\u0645\u06d5) \u0646\u06d5\u0647\u0627\u062a\u0628\u0646\u06d5 \u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646\u060c \u0641\u06c6\u0631\u0645\u0627 \u06a9\u06d5\u06cc\u0633\u0627 \u0646\u0648\u06cc \u0628\u06d5\u0631\u06cc \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u0646\u06ce \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u0646\u06ce \u062f\u062e\u0648\u0627\u0632\u06cc\u062a\u061b \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f \u062f\u0634\u06ce\u062a \u0628\u06ce \u0647\u0627\u0648\u067e\u06ce\u0686 \u0698\u06cc \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a \u0628\u06a9\u06d5\u062a. \u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u06ce\u0646 \u062f\u06a9\u062a\u06c6\u0631\u0627\u0646 \u0646\u0627\u06cc\u06ce\u0646\u06d5 \u06af\u0648\u0647\u06c6\u0695\u06cc\u0646."},
gagp(){return"\u0686 \u0647\u0627\u0648\u067e\u06ce\u0686 \u0646\u06d5\u0647\u0627\u062a\u06cc\u0646\u06d5 \u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646"},
gagn(){return"\u06a4\u06cc \u06a9\u06d5\u06cc\u0633\u06cc \u0686 \u0647\u0627\u0648\u067e\u06ce\u0686 \u0646\u06cc\u0646\u0646 (\u0648\u06ce\u0646\u06d5\u060c \u06a4\u06cc\u062f\u06cc\u06c6\u060c \u0633\u06a9\u0627\u0646 \u06cc\u0627\u0646 \u0628\u06d5\u0644\u06af\u06d5\u0646\u0627\u0645\u06d5). \u062a\u06d5 \u062f\u06a4\u06ce\u062a \u0628 \u0647\u06d5\u0631 \u0631\u06d5\u0646\u06af\u06d5\u06a9\u06cc \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a \u0628\u06a9\u06d5\u06cc\u061f"},
gago(){return"\u0628 \u0647\u06d5\u0631 \u0631\u06d5\u0646\u06af\u06d5\u06a9\u06cc \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a \u0628\u06a9\u06d5"},
gRv(){return"\u0647\u06ce\u0644 \u062f \u0647\u06d5\u0645\u06cc \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u062f\u0627 \u067e\u06ce\u062f\u06a4\u06cc\u06cc\u06d5"},
gRw(){return"\u0633\u06a9\u0627\u0646\u06d5\u0631 (\u06cc\u0627\u0646 \u0698\u0648\u0648\u0631\u0627 \u06a9\u06c6\u0646\u062a\u0631\u06c6\u0644\u06ce) \u0646\u06d5\u0634\u06ce\u062a \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627 \u0646\u0648\u0648 \u067e\u0627\u0634\u06a9\u06d5\u06a4\u062a \u0628\u06a9\u06d5\u062a\u060c \u0648 \u0686 \u06a9\u06d5\u0633 \u0646\u06d5\u0634\u06ce\u062a \u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u0627 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u06ce \u0642\u06d5\u0628\u0648\u0648\u0644 \u0628\u06a9\u06d5\u062a\u060c \u0647\u06d5\u062a\u0627 \u0647\u06ce\u0644\u06d5\u06a9 \u0646\u06d5\u0647\u06ce\u062a\u06d5 \u0647\u06d5\u0644\u0628\u0698\u0627\u0631\u062a\u0646. \u0628\u06d5\u0695\u06ce\u06a4\u06d5\u0628\u06d5\u0631 \u062f \u062f\u06d5\u0645\u06ce \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646\u0627 \u06a9\u06d5\u06cc\u0633\u06ce \u062f\u0627 \u062f\u06d5\u0631\u0686\u0648\u0648\u0646. \u0626\u06d5\u06a4 \u0647\u06d5\u0644\u0628\u0698\u0627\u0631\u062a\u0646\u06d5 \u062a\u0646\u06ce \u0698\u0628\u06d5\u0631 \u0648\u06ce \u062f\u06cc\u0627\u0631\u062f\u0628\u06cc\u062a \u06a9\u0648 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647 \u0647\u06ce\u0644\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u0628\u06a9\u0627\u0631\u062f\u0626\u06cc\u0646\u06cc\u062a."},
